SELECT id, assignment_id, experiment_id, visitor_id, group_id, strategy, hash_key, config_version,
       attributes_json, idempotency_key, assigned_at, created_at, updated_at
FROM pisces_experiment_assignment
WHERE experiment_id = #{experimentId}
  AND visitor_id = #{visitorId}

SELECT COUNT(1)
FROM pisces_experiment_assignment
WHERE experiment_id = #{experimentId}
  AND group_id = #{groupId}
